// Initialize the React state manager with your configuration
const { store, context, hooks } = functions.manageReactState({
  store:   'store',          // name/key for the created Redux store
  context: 'context',        // name/key for the React context provider
  hooks:   'hooks',          // name/key for the custom hooks bundle
  initialState: initialStateObject, // your app's initial state
  reducers:    reducersMap,         // map of reducer functions
  middlewares: [loggerMiddleware],  // array of middleware functions
  enhancers:   [applyMiddleware('myMiddleWare')] // enhancers applied to the store
});
```

This single line creates the store, context, and hooks using the supplied configuration, ready for consumption throughout your React component tree.
